ARP packet for IPv4 over Ethernet: 28 bytes, carried in an Ethernet frame
(EtherType 0x0806), padded to the 46-byte payload minimum.

 0        8        16               31
+-----------------+-----------------+
| Hardware type   | Protocol type   |  0x0001 Ethernet / 0x0800 IPv4
+--------+--------+-----------------+
| HLEN=6 | PLEN=4 | Operation       |  1 request, 2 reply
+--------+--------+-----------------+
| Sender MAC (6 bytes)              |
| Sender IP  (4 bytes)              |
| Target MAC (6 bytes)              |  all zero in a request
| Target IP  (4 bytes)              |
+-----------------------------------+

Request: A asks for 192.168.1.20
 eth dst ff:ff:ff:ff:ff:ff  src aa:aa:aa:aa:aa:aa  type 0x0806
 op=1 SHA=aa:..:aa SPA=192.168.1.10 THA=00:..:00 TPA=192.168.1.20
Reply: B answers A
 eth dst aa:aa:aa:aa:aa:aa  src bb:bb:bb:bb:bb:bb  type 0x0806
 op=2 SHA=bb:..:bb SPA=192.168.1.20 THA=aa:..:aa TPA=192.168.1.10

/* ARP on the wire as a C struct (network byte order) */
#include <stdint.h>
#include <arpa/inet.h>
#include <string.h>

struct arp_ipv4 {
    uint16_t htype;     /* 1 = Ethernet */
    uint16_t ptype;     /* 0x0800 = IPv4 */
    uint8_t  hlen;      /* 6 */
    uint8_t  plen;      /* 4 */
    uint16_t oper;      /* 1 request, 2 reply */
    uint8_t  sha[6];
    uint8_t  spa[4];
    uint8_t  tha[6];
    uint8_t  tpa[4];
} __attribute__((packed));   /* sizeof == 28 */

int is_request_for_me(const struct arp_ipv4 *p, const uint8_t my_ip[4]) {
    return ntohs(p->oper) == 1 && memcmp(p->tpa, my_ip, 4) == 0;
}
